import React, { useState } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState(null);
  const [error, setError] = useState("");

  // 🧠 Parse LLM response into sections
  const parseSummary = (text) => {
    const sections = text.split(/\d\.\s/).filter(Boolean);

    return sections.map((section) => {
      const lines = section.split("\n");
      const title = lines[0];
      const content = lines.slice(1).join(" ");
      return { title, content };
    });
  };

  // 🚀 API CALL
  const handleSubmit = async () => {
    if (!disease.trim()) {
      alert("Enter disease");
      return;
    }

    setLoading(true);
    setError("");
    setData(null);

    try {
      const res = await fetch("http://127.0.0.1:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
        }),
      });

      const result = await res.json();

      if (!res.ok) {
        throw new Error(result.error || "Error");
      }

      setData(result);
    } catch (err) {
      console.error(err);
      setError("Backend error");
    }

    setLoading(false);
  };

  return (
    <div className="app">

      {/* SIDEBAR */}
      <div className="sidebar">
        <h2>Curalink X</h2>

        <input
          placeholder="Disease (e.g. cancer)"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="stats">
          <p>📄 Papers: {data?.meta?.total_papers || 0}</p>
          <p>🧪 Trials: {data?.meta?.total_trials || 0}</p>
        </div>
      </div>

      {/* MAIN */}
      <div className="main">
        <h1>🧠 AI Medical Copilot</h1>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
        />

        <input
          placeholder="Location (optional)"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
        />

        <button onClick={handleSubmit} disabled={loading}>
          {loading ? "⏳ Thinking..." : "Send"}
        </button>

        {error && <p className="error">{error}</p>}

        {/* RESULTS */}
        {data && (
          <div className="results">

            {/* 🧠 INSIGHTS */}
            <div className="card">
              <h2>🧠 AI Insights</h2>

              {parseSummary(data.insights).map((sec, i) => (
                <div key={i} className="block">
                  <h4>{sec.title}</h4>
                  <p>{sec.content}</p>
                </div>
              ))}
            </div>

            {/* 📄 PAPERS */}
            <div className="card">
              <h2>📄 Research Papers</h2>

              {data.publications.map((p, i) => (
                <div key={i} className="item">
                  <h4>{p.title}</h4>
                  <p>{p.year} • {p.source}</p>
                  <a href={p.link} target="_blank">View →</a>
                </div>
              ))}
            </div>

            {/* 🧪 TRIALS */}
            <div className="card">
              <h2>🧪 Clinical Trials</h2>

              {data.clinical_trials.map((t, i) => (
                <div key={i} className="item">
                  <h4>{t.title}</h4>
                  <p>Status: {t.status}</p>
                </div>
              ))}
            </div>

          </div>
        )}
      </div>
    </div>
  );
}

export default App;
